      `#[inline(never)] pub fn ${directory}_unit() -> u8 { 1 }\n#[inline(never)] pub fn ${directory}_example() -> u8 { 4 }\n#[inline(never)] pub fn ${directory}_integration() -> u8 { ${directory === "core" ? 'if let Some(path) = std::env::var_os("MESH_AFTER_TIMEOUT_MARKER") { std::fs::write(path, "continued after timeout").unwrap(); }' : ""} 2 }\n#[test] fn unit() { assert_eq!(${directory}_unit(), 1); ${directory === "host" ? 'assert!(std::env::var_os("MESH_FAIL_HOST").is_none(), "host failure control");' : 'if let Some(path) = std::env::var_os("MESH_REST_MARKER") { std::fs::write(path, "rest execution").unwrap(); } assert!(std::env::var_os("MESH_FAIL_CORE").is_none(), "core failure control"); if let Some(path) = std::env::var_os("MESH_PARK_CORE") { std::fs::write(path, "park entered").unwrap(); loop { std::thread::park(); } }'} }\n#[test] #[ignore] fn default_ignored() { panic!("must remain ignored"); }\n`,
    );
    writeFileSync(
      join(root, directory, "tests/default.rs"),
      `#[test] fn integration() { assert_eq!(${crate}::${directory}_integration(), 2); }\n`,
    );
    writeFileSync(
      join(root, directory, "src/main.rs"),
      `#[inline(never)] fn ${directory}_binary() -> u8 { 3 }\nfn main() {}\n#[test] fn binary() { assert_eq!(${directory}_binary(), 3); }\n`,
    );
    writeFileSync(
      join(root, directory, "examples/default.rs"),
      `fn main() {}\n#[test] fn example() { assert_eq!(${crate}::${directory}_example(), 4); }\n`,
    );
  }
  const env = {
    ...process.env,
    CARGO_TARGET_DIR: join(root, "target"),
    CARGO_LLVM_COV_TARGET_DIR: join(root, "coverage-target"),
    CARGO_TERM_COLOR: "never",
  };
  delete env.LLVM_PROFILE_FILE;
  const run = (args, extra = {}, expected = 0) => {
    const result = spawnSync("cargo", args, {
      cwd: root,
      env: { ...env, ...extra },
      encoding: "utf8",
      timeout: 120_000,
      maxBuffer: 8 * 1024 * 1024,
    });
    assert.equal(
      result.status,
      expected,
      `${args.join(" ")}\n${result.error ?? ""}\n${result.stdout}\n${result.stderr}`,
    );
    return result.stdout + result.stderr;
  };
  run(["generate-lockfile", "--offline"]);
  const deferred = spawnSync("bash", [helper, "linux", "--defer-report"], {
    cwd: root, env: { ...env, MESH_TALK_TEST_TIMING: "0", RUNNER_TEMP: root },
    encoding: "utf8", timeout: 120_000,
  });
  assert.equal(deferred.status, 0, `${deferred.error ?? ""}\n${deferred.stdout}\n${deferred.stderr}`);
  assert.equal((deferred.stdout + deferred.stderr).match(/4 tests run: 4 passed, 1 skipped/gu)?.length, 2);
  assert.equal(existsSync(join(root, "lcov.info")), false, "the actual deferred CLI must not produce a completed report");
  run(["llvm-cov", "report", "--lcov", "--output-path", "lcov.info"]);
  // llvm-cov intentionally excludes examples/ and tests/ from its default report.
  // Each example therefore calls its own library sentinel, so a real hit proves
  // execution without changing the production coverage denominator.
  const coverage = readFileSync(join(root, "lcov.info"), "utf8");
  for (const directory of ["host", "core"])
    for (const target of ["unit", "integration", "binary", "example"]) {
      assert.match(
        coverage,
        new RegExp(`^FNDA:[1-9]\\d*,[^\\n]*${directory}_${target}`, "m"),
        `${directory} ${target} coverage must accumulate`,
      );
    }
  assert.match(
    workflow,
    /bash \.\.\/scripts\/ci\/workspace-coverage\.sh macos/u,
  );
  assert.match(
    workflow,
    /bash \.\.\/scripts\/ci\/workspace-coverage\.sh linux/u,
  );
  const blockMac = "macos";
  // Execute the actual macOS block in a clean coverage cohort. Core's real
  // default targets must run, but must not require another instrumented build.
  run(["llvm-cov", "clean", "--workspace"]);
  const macMarker = join(root, "mac-core-executed");
  const macPass = spawnSync("bash", [helper, blockMac], {
    cwd: root,
    env: {
      ...env,
      MESH_REST_MARKER: macMarker,
      MESH_TALK_TEST_TIMING: "0",
      RUNNER_TEMP: root,
    },
    encoding: "utf8",
    timeout: 120_000,
  });
  assert.equal(macPass.status, 0, macPass.stdout + macPass.stderr);
  assert.equal(
    (macPass.stdout + macPass.stderr).match(
      /4 tests run: 4 passed, 1 skipped/gu,
    )?.length,
    2,
  );
  assert.equal(readFileSync(macMarker, "utf8"), "rest execution");
  const macCoverage = readFileSync(join(root, "lcov.info"), "utf8");
  assert.match(macCoverage, /^FNDA:[1-9]\d*,[^\n]*host_unit/mu);
  assert.doesNotMatch(
    macCoverage,
    /^FNDA:[1-9]\d*,[^\n]*core_/mu,
    "macOS must execute Core normally while Linux/Windows own its full instrumented coverage",
  );
  const linuxBlock = "linux";
  for (const block of [blockMac, linuxBlock, "linux-deferred"]) {
    const blockArgs = block === "linux-deferred" ? ["linux", "--defer-report"] : [block];
    rmSync(join(root, "lcov.info"), { recursive: true, force: true });
    writeFileSync(join(root, "lcov.info"), "previous report");
    for (const failure of ["HOST", "CORE", "BOTH"]) {
      for (const timing of ["0", "1"]) {
        rmSync(join(root, "lcov.info"));
        const marker = join(
          root,
          `rest-${block}-${failure}-${timing}`,
        );
        const failedPartition = spawnSync("bash", [helper, ...blockArgs], {
          cwd: root,
          env: {
            ...env,
            ...(failure === "BOTH"
              ? { MESH_FAIL_HOST: "1", MESH_FAIL_CORE: "1" }
              : { [`MESH_FAIL_${failure}`]: "1" }),
            MESH_REST_MARKER: marker,
            MESH_TALK_TEST_TIMING: timing,
            RUNNER_TEMP: root,
          },
          encoding: "utf8",
          timeout: 120_000,
        });
        assert.equal(
          failedPartition.status,
          100,
          `${failedPartition.error ?? ""}\n${failedPartition.stdout}\n${failedPartition.stderr}`,
        );
        const diagnostic = failedPartition.stdout + failedPartition.stderr;
        if (process.platform === "darwin" && block === blockMac) {
          assert.match(diagnostic, /native-resource phase=host/u);
          assert.match(diagnostic, /maximum resident set size/u);
          assert.match(diagnostic, /hw\.memsize:/u);
          assert.match(diagnostic, /vm\.swapusage:/u);
          if (failure === "CORE")
            assert.match(diagnostic, /native-resource phase=remaining/u);
          else
            assert.doesNotMatch(diagnostic, /native-resource phase=remaining/u);
        } else {
          assert.doesNotMatch(diagnostic, /native-resource phase=/u);
        }
        assert.match(
          failedPartition.stdout + failedPartition.stderr,
          new RegExp(
            `${failure === "BOTH" ? "host" : failure.toLowerCase()} failure control`,
            "u",
          ),
        );
        assert.equal(
          existsSync(marker),
          failure === "CORE",
          "only a passing Host may admit the remaining workspace partition",
        );
        if (failure === "BOTH")
          assert.doesNotMatch(
            failedPartition.stdout + failedPartition.stderr,
            /core failure control/u,
            "a failed Host must stop before starting another compilation/test partition",
          );
        assert.equal(
          existsSync(join(root, "lcov.info")),
          false,
          "either failed partition must stop before report",
        );
        if (timing === "1")
          assert.match(
            readFileSync(join(root, "mesh-talk-test-timing.log"), "utf8"),
            new RegExp(
              `${failure === "BOTH" ? "host" : failure.toLowerCase()} failure control`,
              "u",
            ),
          );
        // Restore the report only for the next independent failure-control iteration.
        writeFileSync(join(root, "lcov.info"), "previous report");
      }
    }
    if (block === "linux-deferred") continue;
    for (const timing of ["0", "1"]) {
      rmSync(join(root, "lcov.info"), { recursive: true, force: true });
      // A real report destination failure must fail even after both suites pass.
      mkdirSync(join(root, "lcov.info"));
      const reportFailure = spawnSync("bash", [helper, ...blockArgs], {
        cwd: root,
        env: { ...env, MESH_TALK_TEST_TIMING: timing, RUNNER_TEMP: root },
        encoding: "utf8",
        timeout: 120_000,
      });
      assert.equal(reportFailure.error, undefined);
      assert.notEqual(
        reportFailure.status,
        0,
        reportFailure.stdout + reportFailure.stderr,
      );
      assert.equal(
        (reportFailure.stdout + reportFailure.stderr).match(
          /4 tests run: 4 passed, 1 skipped/gu,
        )?.length,
        2,
        "report failure must remain nonzero after both complete partitions pass",
      );
    }
  }
  rmSync(join(root, "lcov.info"), { recursive: true, force: true });
  const emptyHost = run([...host, "-E", "test(=absent_case)"], {}, 4);
  assert.match(emptyHost, /no tests/u);
  const emptyRest = run([...rest, "-E", "test(=absent_case)"], {}, 4);
  assert.match(emptyRest, /no tests/u);

  // Parse the actual source default, accelerating ONLY its period in this
  // isolated fixture. Keep all fifteen periods and the real grace/exception
  // policy; a one-period hand-written override would not prove the default.
  const defaultTimeout =
    'slow-timeout = { period = "60s", terminate-after = 15, grace-period = "5s" }';
  const accelerated = replaceNextestProfileText(
    config,
    "default",
    defaultTimeout,
    defaultTimeout.replace('period = "60s"', 'period = "100ms"'),
  );
  assert.match(
    accelerated,
    /period = "100ms", terminate-after = 15, grace-period = "5s"/u,
  );
  writeFileSync(
    join(root, ".config/nextest.toml"),
    `${accelerated}\n[[profile.default.overrides]]\nfilter = 'package(=mesh-talk-core) & test(=unit)'\npriority = 100\n`,
  );
  const parkEntered = join(root, "park-entered");
  const afterTimeout = join(root, "after-timeout");
  const serialRest = [...rest];
  serialRest[serialRest.indexOf("--test-threads") + 1] = "1";
  const timedOut = run(
    serialRest,
    {
      MESH_PARK_CORE: parkEntered,
      MESH_AFTER_TIMEOUT_MARKER: afterTimeout,
    },
    100,
  );
  assert.match(timedOut, /TIMEOUT|timed out/iu);
  assert.equal(readFileSync(parkEntered, "utf8"), "park entered");
  assert.equal(readFileSync(afterTimeout, "utf8"), "continued after timeout");
});
# Native macOS critical-path design

Extend existing windows-coverage.mjs with optional trusted profile macos-remaining; default Windows API/CLI and eight serial fully instrumented partitions unchanged. Mac profile selects --workspace --exclude mesh-talk --locked, two hash partitions, four test workers, zero retries, no-fail-fast, default ignored policy, no coverage instrumentation. All selected enabled Cargo default targets must match metadata; never weaken generic full/partition validators or accept an omitted package. Exact producer and consumer source/root/compiler/ABI/profile/config/features/attempt and trusted manifest/archive digests; same absolute checkout/target required by embedded CARGO_BIN_EXE. No LCOV invented for uninstrumented consumers. Existing validators and command owner reused, no new generic framework.

CI Ubuntu existing implementation stays intact as explicit name checks (ubuntu-latest), avoiding shared matrix needs. Independent macOS native lane retains Clippy all-targets, ordinary production build, Host instrumentation/report and all workspace doctests; extend workspace-coverage.sh with Host-only mode, keep standalone existing macos behavior. Immediate macOS remaining producer requires only checkout, Node script runtime, Rust and Nextest plus its appropriate dependency cache: Core/Integrations/MCP have no build.rs, frontend references or node/npm subprocesses, so this lane and archive consumers need no frontend npm install/build/npm cache or LLVM tools. Native Host lane still prepares frontendDist normally. Verify this assumption with exact selected metadata/actual hosted compilation, not merely rg.

Two consumers use only checkout/runtime/toolchain setup, download sealed archive, no Rust cache, no compilation or frontend dependency cache. Extract target at exact original absolute root. Native defaults/pinned config and all target inventories/executions unchanged. A stable Ubuntu final collector named checks (macos-latest) explicitly requires native lane/producer/both consumers success and validates their source/run/attempt identities, trusted hashes, receipts and exact disjoint union. Docs scope retains verified cheap final checks and zero fake receipts. Single Codecov empty upload remains Ubuntu only; full native Host report uploads from its native lane as before.

Qualification: actual pinned local native fixture with workspace metadata that has Host plus remaining packages and a real embedded CLI path; empty archive-only consumers after removing producer outputs; wrong roots/digests/profile/compiler/config/attempt/source, omitted/added targets, duplicates/missing/partial execution, ignored policy and no fake LCOV reject. Existing unchanged Windows actual fixture must still pass. Existing native Host accumulation fixtures must prove new Host-only mode and preserve standalone behavior/failures. Keep current 33 protected names/app bindings. Extend existing validation selectors and CI/reliability owning guide paragraphs, not new report owners.

Resource limits: old macOS checks47m26 includes remaining compile17m26+execution14m02 after serial other work. Parallel native lane ~15m and immediate archive producer ~20m plus2consumer tail~7m is plausible high20s before queues; not evidence or30min guarantee. More jobs add setup and share5Mac/20global slots with browser/backend/native checks. Preserve UI Health/WebKit admission and measure complete same-source DAG. Linux stays current direct accumulated coverage first: uploading early in a job does not release needs consumers before job completion. An archive-based ignored backend consumer requires separate qualified adaptation in its existing evidence owner.

Design review qualifications: explicitly enforce metadata target-directory==root/target, not just internal debug/deps layout. Mac identity rejects or explicitly normalizes/binds target/build-dir overrides, Rust wrappers/flags, LLVM_PROFILE_FILE and all llvm-cov activation variables; retain exact accepted profile environments and feature graph. Do not merely remove Windows show-env requirement. Collector uses producer job-output digests rather than trusting artifact/self-reported hashes, checks actual job outcomes independently and all source/run/attempt/profile/execution/union evidence. Keep diagnostics and native real-tool fixtures in native lane. Existing POSIX command wrapper proves process-group handling only, not all independently grouped Nextest descendants; fresh hosted job acceptance remains fail-closed with no failed receipts and bounded watchdogs, no unproven cleanup claim. Local cancellation fixture must own/join actual child before temporary cleanup, no PID sweeps/new speculative framework. Independent design source review approved with these constraints; no hosted result yet.

Environment qualification: .cargo/config.toml defaults compile jobs4, but old macOS workspace-coverage.sh explicitly bounds Host/remaining to2. New remaining producer must explicitly retain CARGO_BUILD_JOBS=2; consumers use testThreads/RUST_TEST_THREADS4. Swatinem/rust-cache sets CARGO_INCREMENTAL=0 (observed actual baseline logs); consumers deliberately have no rust-cache, so explicitly align/bind CARGO_INCREMENTAL=0 and accepted DEV/TEST line-tables-only environment rather than depending on action side effects. Mac jobs use fixed CARGO_TARGET_DIR=$GITHUB_WORKSPACE/target as needed, not global CI target overrides that would disturb Linux llvm-cov target ownership. Keep native lane ordinary static build defaults independently owned as before. Collector cross-platform validation is pure: validate source/config/job-output manifest authority and execution identities; do not compare its Ubuntu runtime platform/root to the Darwin producer runtime. Consumer/native identity remains exact.
