test("uninstrumented macOS archive rejects inherited compilation and target overrides", () => {
  const root = process.cwd();
  const env = { CARGO_BUILD_JOBS: "2", CARGO_INCREMENTAL: "0", CARGO_PROFILE_DEV_DEBUG: "line-tables-only", CARGO_PROFILE_TEST_DEBUG: "line-tables-only", CARGO_TARGET_DIR: `${root}/target` };
