  const metadata = { workspace_members: packages.map(pkg => pkg.id), packages, resolve: { nodes: packages.map(pkg => ({ id: pkg.id, features: [] })) } };
  const suite = id => ({ "package-id": id, kind: "lib", "binary-name": id });
  const listing = { "rust-suites": { remaining: suite("remaining"), new: suite("new") } };
  verifyTargets(listing, metadata, "macos-remaining");
  assert.throws(() => verifyTargets({ "rust-suites": { remaining: suite("remaining") } }, metadata, "macos-remaining"), /target/);
  assert.throws(() => verifyTargets({ "rust-suites": { ...listing["rust-suites"], host: suite("host") } }, metadata, "macos-remaining"), /target/);
  assert.throws(() => verifyTargets(listing, { ...metadata, packages: packages.slice(1), workspace_members: ["remaining", "new"] }, "macos-remaining"), /Host/);
});

test("layout must match the original checkout target, not just internally consistent binary paths", () => {
