  const put = (directory, name, value) => { const text = JSON.stringify(value); writeFileSync(path.join(directory, name), text); return hash(text); };
  const all = inventory(listing(["a", "b", "c", "d"]));
  const shards = [["a", "b"], ["c", "d"]].map(names => inventory(listing(names)));
  const inventoryFiles = Object.fromEntries([all, ...shards].map((rows, index) => [`inventory-${index}.json`, put(root, `inventory-${index}.json`, rows)]));
  const identity = { archiveProfile: "macos-remaining", sourceSha: "a".repeat(40), runId: "1", runAttempt: "2", platform: "darwin", arch: "arm64", root: "/darwin/source", rustc: "rustc native", cargo: "cargo native", cargoConfigSha256: hash("cargo config"), nextestConfigSha256: hash("nextest config"), buildArgs: archiveProfile("macos-remaining").buildArgs };
  const archiveSha256 = hash("archive bytes not present on collector");
  const manifest = { schema: 1, identity, archiveSha256, inventoryFiles, featureResolutionSha256: hash("features"), testCount: all.length, runnableCount: 4, scheduling: { partitions: 2, partition: "hash", testThreads: 4, retries: 0, ignored: "default" } };
  const manifestSha256 = put(root, "manifest.json", manifest);
  const outputs = shards.map((rows, index) => {
    const output = path.join(root, `result-${index}`); mkdirSync(output);
    const selectedInventorySha256 = put(output, "selected-inventory.json", rows);
    const events = rows.filter(row => row.selected).flatMap(row => ["started", "ok"].map(event => JSON.stringify({ type: "test", event, name: row.eventName }))).join("\\n");
    writeFileSync(path.join(output, "execution.jsonl"), events);
    put(output, "receipt.json", { schema: 1, identity, sourceSha: identity.sourceSha, runId: "1", runAttempt: "2", shard: index + 1, archiveSha256, manifestSha256, inventoryFiles, featureResolutionSha256: manifest.featureResolutionSha256, selectedInventorySha256, executionSha256: hash(events), executedTests: 2, totalTests: all.length, seconds: 0.1 });
    return output;
  });
  const trusted = { manifestSha256, archiveSha256, sourceSha: identity.sourceSha, runId: "1", runAttempt: "2", jobResults: { native: "success", producer: "success", consumers: ["success", "success"] } };
  assert.equal((await collectMacRemaining(root, outputs, trusted)).executedTests, 4);
  for (const field of ["manifestSha256", "archiveSha256", "sourceSha", "runId", "runAttempt"])
    await assert.rejects(collectMacRemaining(root, outputs, { ...trusted, [field]: field.endsWith("Sha256") ? hash("wrong") : "wrong" }));
  for (const status of ["failure", "cancelled", "skipped", ""]) {
    await assert.rejects(collectMacRemaining(root, outputs, { ...trusted, jobResults: { ...trusted.jobResults, native: status } }), /job/);
    await assert.rejects(collectMacRemaining(root, outputs, { ...trusted, jobResults: { ...trusted.jobResults, consumers: ["success", status] } }), /job/);
  }
  await assert.rejects(collectMacRemaining(root, [outputs[0]], trusted), /receipt/);
  await assert.rejects(collectMacRemaining(root, [outputs[0], outputs[0]], trusted), /shard/);
  const receipt = JSON.parse(readFileSync(path.join(outputs[0], "receipt.json"), "utf8"));
  for (const changed of [{ ...receipt, identity: { ...identity, rustc: "changed" } }, { ...receipt, coverageSha256: hash("fake LCOV") }, { ...receipt, executedTests: 1 }, { ...receipt, featureResolutionSha256: hash("wrong") }, { ...receipt, manifestSha256: hash("wrong") }]) {
    put(outputs[0], "receipt.json", changed);
    await assert.rejects(collectMacRemaining(root, outputs, trusted));
  }
  put(outputs[0], "receipt.json", receipt);
  const eventsFile = path.join(outputs[0], "execution.jsonl");
  const events = readFileSync(eventsFile, "utf8");
  writeFileSync(eventsFile, events.split("\\n").slice(0, -1).join("\\n"));
  await assert.rejects(collectMacRemaining(root, outputs, trusted), /execution/);
  put(outputs[0], "receipt.json", { ...receipt, executionSha256: hash(readFileSync(eventsFile)) });
  await assert.rejects(collectMacRemaining(root, outputs, trusted), /execution/);
});
