// collector's platform/root or an artifact's self-reported checksum.
export async function collectMacRemaining(directory, outputs, trusted) {
  requireDigest(trusted?.manifestSha256); requireDigest(trusted?.archiveSha256);
  assert.deepEqual(trusted.jobResults, { native: "success", producer: "success", consumers: ["success", "success"] }, "All native archive job results must be success");
  assert.match(trusted.sourceSha ?? "", /^[a-f0-9]{40}$/u, "Expected source SHA required");
  assert.match(trusted.runId ?? "", /^[1-9]\\d*$/u, "Expected run ID required");
  assert.match(trusted.runAttempt ?? "", /^[1-9]\\d*$/u, "Expected attempt required");
  assert.equal(await fileHash(path.join(directory, "manifest.json")), trusted.manifestSha256, "Trusted manifest digest mismatch");
  const manifest = readJson(path.join(directory, "manifest.json"));
  const profile = archiveProfile("macos-remaining");
  assert.equal(manifest.schema, 1, "Unsupported archive manifest");
  assert.equal(manifest.identity.archiveProfile, profile.name, "Wrong archive profile");
  assert.equal(manifest.identity.platform, "darwin", "Wrong producer platform");
  for (const key of ["sourceSha", "runId", "runAttempt"]) assert.equal(manifest.identity[key], trusted[key], `Stale producer ${key}`);
  assert.equal(manifest.archiveSha256, trusted.archiveSha256, "Trusted archive digest mismatch");
  assert.deepEqual(manifest.scheduling, scheduling(profile), "Wrong archive scheduling");
  const expected = [];
  assert.deepEqual(Object.keys(manifest.inventoryFiles).sort(), ["inventory-0.json", "inventory-1.json", "inventory-2.json"], "Unexpected inventory files");
  for (let index = 0; index <= 2; index++) {
    const name = `inventory-${index}.json`;
    assert.equal(await fileHash(path.join(directory, name)), manifest.inventoryFiles[name], "Producer inventory digest mismatch");
    expected.push(readJson(path.join(directory, name)));
  }
  verifyPartition(expected[0], expected.slice(1), 2);
  assert.equal(manifest.testCount, expected[0].length, "Producer total test count mismatch");
  assert.equal(manifest.runnableCount, expected[0].filter(row => row.selected).length, "Producer runnable count mismatch");
  assert.equal(outputs.length, 2, "Exactly two consumer receipts required");
  const seen = new Set();
  for (const output of outputs) {
    const receipt = readJson(path.join(output, "receipt.json"));
    assert.equal(receipt.schema, 1, "Unsupported consumer receipt");
    assert.ok(profile.partitions.includes(receipt.shard) && !seen.has(receipt.shard), "Missing or duplicate consumer shard");
    seen.add(receipt.shard);
    assert.ok(!("coverage" in receipt) && !("coverageSha256" in receipt), "Uninstrumented receipt cannot claim coverage");
    verifyIdentity(manifest.identity, receipt.identity);
    for (const key of ["sourceSha", "runId", "runAttempt"]) assert.equal(receipt[key], trusted[key], `Stale receipt ${key}`);
    assert.equal(receipt.archiveSha256, trusted.archiveSha256, "Receipt archive digest mismatch");
    assert.equal(receipt.manifestSha256, trusted.manifestSha256, "Receipt manifest digest mismatch");
    assert.equal(receipt.featureResolutionSha256, manifest.featureResolutionSha256, "Receipt feature graph differs");
    assert.deepEqual(receipt.inventoryFiles, manifest.inventoryFiles, "Receipt inventories differ");
    const selectedFile = path.join(output, "selected-inventory.json");
    assert.equal(await fileHash(selectedFile), receipt.selectedInventorySha256, "Selected inventory digest mismatch");
    const selected = readJson(selectedFile);
    assert.deepEqual(selected, expected[receipt.shard], "Selected partition differs");
    assert.equal(receipt.executedTests, selected.filter(row => row.selected).length, "Execution count differs");
    assert.equal(receipt.totalTests, expected[0].length, "Total inventory count differs");
    assert.ok(Number.isFinite(receipt.seconds) && receipt.seconds >= 0, "Invalid execution duration");
    const execution = path.join(output, "execution.jsonl");
    assert.equal(await fileHash(execution), receipt.executionSha256, "execution digest mismatch");
    verifyExecution(readFileSync(execution, "utf8"), selected);
  }
  return { sourceSha: trusted.sourceSha, runId: trusted.runId, runAttempt: trusted.runAttempt, archiveSha256: trusted.archiveSha256, manifestSha256: trusted.manifestSha256, executedTests: manifest.runnableCount };
}''')
