// Native pinned-tool qualification; intentionally outside portable diagnostics.
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { createHash } from "node:crypto";
import { copyFileSync, existsSync, mkdtempSync, mkdirSync, readFileSync, renameSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";
import test from "node:test";
import { collectMacRemaining } from "./windows-coverage.mjs";

const runner = fileURLToPath(new URL("./windows-coverage.mjs", import.meta.url));
const hash = text => createHash("sha256").update(text).digest("hex");
test("real macOS archive excludes Host and executes complete offline remaining targets at the original root", { timeout: 120000 }, async t => {
  assert.equal(process.platform, "darwin", "Run this qualification in the native macOS producer");
  const temporary = mkdtempSync(path.join(tmpdir(), "mesh-mac-archive-"));
  t.after(() => rmSync(temporary, { recursive: true, force: true }));
  const root = path.join(temporary, "source");
  const write = (file, text) => writeFileSync(path.join(root, file), text);
  for (const directory of [".cargo", ".config", "empty-hooks", "host/src", "core/src", "core/tests", "core/examples", "extra/src"])
    mkdirSync(path.join(root, directory), { recursive: true });
  write(".gitignore", "/target/\n");
  write(".cargo/config.toml", '[build]\njobs=4\n[env]\nRUST_TEST_THREADS="4"\n');
  write(".config/nextest.toml", 'nextest-version="0.9.150"\n[profile.default]\nslow-timeout={period="60s",terminate-after=15,grace-period="5s"}\n');
  write("Cargo.toml", '[workspace]\nmembers=["host","core","extra"]\nresolver="2"\n');
  write("host/Cargo.toml", '[package]\nname="mesh-talk"\nversion="0.0.0"\nedition="2024"\nbuild="build.rs"\n');
  write("host/src/lib.rs", '#[test] fn host_must_not_run() { panic!("Host selected"); }\n');
  write("host/build.rs", 'fn main() { panic!("Host must not compile or need frontend"); }\n');
  write("core/Cargo.toml", '[package]\nname="remaining-core"\nversion="0.0.0"\nedition="2024"\n[[example]]\nname="default-example"\ntest=true\n[features]\ndefault=["enabled"]\nenabled=[]\n[[test]]\nname="enabled"\nrequired-features=["enabled"]\n[[test]]\nname="disabled"\nrequired-features=["disabled"]\n');
  const body = 'assert_eq!(std::env::var("RUST_TEST_THREADS").unwrap(), "4"); assert!(std::env::var_os("LLVM_PROFILE_FILE").is_none()); assert!(std::env::var_os("MESH_MAC_FAIL").is_none(), "intentional remaining failure");';
  write("core/src/lib.rs", `${Array.from({ length: 16 }, (_, index) => `#[test] fn case_${index}() { ${body} }`).join("\n")}\n#[test] #[ignore] fn ignored() { panic!("must stay ignored"); }\n`);
  write("core/src/main.rs", `fn main() { println!("embedded helper"); }\n#[test] fn binary() { ${body} }\n`);
  write("core/tests/enabled.rs", `#[test] fn embedded_cli() { ${body} for binary in [env!("CARGO_BIN_EXE_remaining-core").to_owned(), std::env::var("CARGO_BIN_EXE_remaining-core").unwrap()] { assert!(std::process::Command::new(binary).output().unwrap().status.success()); } }\n`);
  write("core/tests/disabled.rs", 'compile_error!("disabled target must not compile");\n');
  write("core/examples/default-example.rs", `fn main() {}\n#[test] fn example() { ${body} }\n`);
  write("extra/Cargo.toml", '[package]\nname="new-remaining"\nversion="0.0.0"\nedition="2024"\n');
  write("extra/src/lib.rs", `#[test] fn new_workspace_package() { ${body} }\n`);
  copyFileSync(runner, path.join(root, "windows-coverage.mjs"));
  const env = { ...process.env, CARGO_NET_OFFLINE: "true", CARGO_TERM_COLOR: "never", CARGO_BUILD_JOBS: "2", CARGO_INCREMENTAL: "0", CARGO_PROFILE_DEV_DEBUG: "line-tables-only", CARGO_PROFILE_TEST_DEBUG: "line-tables-only", CARGO_TARGET_DIR: path.join(root, "target"), RUST_TEST_THREADS: "4" };
  for (const key of Object.keys(env))
