async function list(args, options) { return JSON.parse(await command(["nextest", "list", ...nextestArgs, ...args, "--message-format", "json"], options)); }
export function verifyLayout(binaries, root) {
  const metadata = binaries["rust-build-meta"];
  assert.ok(typeof metadata?.["target-directory"] === "string" && path.isAbsolute(metadata["target-directory"]), "Missing absolute archive target directory");
  const normalize = value => process.platform === "win32" ? path.resolve(value).toLowerCase() : path.resolve(value);
  const target = normalize(metadata["target-directory"]);
  if (root !== undefined) assert.equal(target, normalize(path.join(root, "target")), "Archive target directory differs from checkout target");
  assert.ok(!metadata["build-directory"] || normalize(metadata["build-directory"]) === target, "Unsupported separate build directory (upstream cargo-llvm-cov #520)");
  for (const binary of Object.values(binaries["rust-binaries"])) {
    const expected = normalize(path.join(target, "debug", binary.kind === "example" ? "examples" : "deps"));
    assert.ok(path.isAbsolute(binary["binary-path"]) && normalize(path.dirname(binary["binary-path"])) === expected, "Unsupported build layout/profile (upstream cargo-llvm-cov #520); expected v1 target/debug/deps or example target/debug/examples");
  }
}

export async function produce(directory, { profile: profileName = "windows" } = {}) {
  const profile = archiveProfile(profileName);
  const before = await identity(undefined, profile);
  const archive = path.join(directory, "workspace.tar.zst");
  assert.ok(!existsSync(archive), "Archive already exists");
  mkdirSync(directory, { recursive: true });
  await command(["nextest", "archive", ...nextestArgs, ...profile.buildArgs, "--archive-file", archive]);
  const probe = path.join(directory, "inventory-extract");
  mkdirSync(probe, { recursive: true });
  const binaries = await list(["--archive-file", archive, "--extract-to", probe, "--list-type", "binaries-only"]);
  verifyLayout(binaries, process.cwd());
  const binaryFile = path.join(directory, "producer-binaries.json");
  writeJson(binaryFile, binaries);
  const metadataFile = path.join(probe, "target", "nextest", "cargo-metadata.json");
  const metadata = readJson(metadataFile);
  const reuse = ["--binaries-metadata", binaryFile, "--cargo-metadata", metadataFile, "--target-dir-remap", path.join(probe, "target")];
  const listings = [await list(reuse)];
  for (const shard of profile.partitions) listings.push(await list([...reuse, "--partition", `hash:${shard}/${profile.partitions.length}`]));
  verifyTargets(listings[0], metadata, profile.name);
  const inventories = listings.map(inventory);
  verifyPartition(inventories[0], inventories.slice(1), profile.partitions.length);
  const files = {};
  for (let index = 0; index < inventories.length; index++) {
    const name = `inventory-${index}.json`;
    writeJson(path.join(directory, name), inventories[index]);
    files[name] = await fileHash(path.join(directory, name));
  }
  const featureResolutionSha256 = digest(canonical(metadata.resolve));
  verifyIdentity(before, await identity(undefined, profile));
  const archiveSha256 = await fileHash(archive);
  writeJson(path.join(directory, "manifest.json"), { schema: 1, identity: before, archiveSha256, inventoryFiles: files, featureResolutionSha256, testCount: inventories[0].length, runnableCount: inventories[0].filter(row => row.selected).length, scheduling: scheduling(profile) });
  rmSync(probe, { recursive: true });
  rmSync(binaryFile);
  console.log(`Archived ${inventories[0].length} tests; ${inventories[0].filter(row => row.selected).length} runnable across ${profile.partitions.length} verified shards.`);
  return { archiveSha256, manifestSha256: await fileHash(path.join(directory, "manifest.json")), rustVersion: /^rustc ([^ ]+)/u.exec(before.rustc)?.[1] };
}

export function consumerFailurePolicy(env = process.env) {
  const value = env.MESH_WINDOWS_FAIL_FAST;
  assert.ok(value === undefined || value === "0" || value === "1", "MESH_WINDOWS_FAIL_FAST must be 0 or 1");
  return value === "1" ? "--fail-fast" : "--no-fail-fast";
}

export async function consume(shard, directory, output, { profile: profileName = "windows", manifestSha256, archiveSha256 } = {}) {
  const profile = archiveProfile(profileName);
  assert.ok(profile.partitions.includes(shard), `shard must be an integer from 1 through ${profile.partitions.length}`);
  if (!profile.instrumented) {
    requireDigest(manifestSha256); requireDigest(archiveSha256);
    assert.equal(await fileHash(path.join(directory, "manifest.json")), manifestSha256, "Trusted manifest digest mismatch");
  }
  mkdirSync(output, { recursive: true });
  const progress = path.join(output, "progress.jsonl");
  assert.ok(!existsSync(progress) && !existsSync(path.join(output, "receipt.json")), "Consumer output already contains a prior attempt");
  const evidence = phase => ({ progress, phase, receipt: path.join(output, phase) });
  const manifest = readJson(path.join(directory, "manifest.json"));
  assert.equal(manifest.schema, 1, "Unsupported archive manifest");
  verifyIdentity(manifest.identity, await identity(evidence, profile));
  assert.deepEqual(manifest.scheduling, scheduling(profile));
  if (!profile.instrumented) assert.equal(manifest.archiveSha256, archiveSha256, "Trusted archive digest mismatch");
  const archive = path.join(directory, "workspace.tar.zst");
  assert.equal(await fileHash(archive), manifest.archiveSha256, "Archive digest mismatch");
  const expected = [];
  for (let index = 0; index <= profile.partitions.length; index++) {
    const name = `inventory-${index}.json`;
    assert.equal(await fileHash(path.join(directory, name)), manifest.inventoryFiles[name], "Inventory digest mismatch");
    expected.push(readJson(path.join(directory, name)));
  }
  verifyPartition(expected[0], expected.slice(1), profile.partitions.length);
  // Never reuse producer build outputs accidentally: this proves archive-only execution.
  assert.ok(profile.instrumented ? !existsSync(path.join(process.cwd(), "target", "debug")) : !existsSync(path.resolve("target")) || readdirSync(path.resolve("target")).length === 0, "Consumer target contains prior compilation outputs");
  writeJson(path.join(output, "expected-inventory.json"), expected[shard]);
  writeJson(path.join(output, "input-identity.json"), { sourceSha: manifest.identity.sourceSha, runId: manifest.identity.runId, runAttempt: manifest.identity.runAttempt, shard, archiveSha256: manifest.archiveSha256 });
  const binaries = await list(["--archive-file", archive, "--extract-to", process.cwd(), "--list-type", "binaries-only"], evidence("extract"));
  verifyLayout(binaries, process.cwd());
  const binaryFile = path.join(output, "consumer-binaries.json");
  writeJson(binaryFile, binaries);
  const metadataFile = path.resolve("target/nextest/cargo-metadata.json");
  const metadata = readJson(metadataFile);
  assert.equal(digest(canonical(metadata.resolve)), manifest.featureResolutionSha256, "Archived feature resolution changed");
  const reuse = ["--binaries-metadata", binaryFile, "--cargo-metadata", metadataFile, "--target-dir-remap", path.resolve("target")];
  const listings = [await list(reuse, evidence("inventory-all"))];
  for (const index of profile.partitions) listings.push(await list([...reuse, "--partition", `hash:${index}/${profile.partitions.length}`], evidence(`inventory-${index}`)));
  verifyTargets(listings[0], metadata, profile.name);
  const observed = listings.map(inventory);
  verifyPartition(observed[0], observed.slice(1), profile.partitions.length);
  assert.deepEqual(observed, expected, "Consumer partition differs from producer inventory");
  writeJson(path.join(output, "selected-inventory.json"), observed[shard]);
  const started = performance.now();
  const events = await command(["nextest", "run", ...nextestArgs, ...reuse, "--partition", `hash:${shard}/${profile.partitions.length}`, "--test-threads", String(profile.testThreads), "--retries", "0", profile.instrumented ? consumerFailurePolicy() : "--no-fail-fast", "--no-tests", "fail", ...(process.env.MESH_TALK_TEST_TIMING === "1" ? ["--success-output", "final"] : []), "--message-format", "libtest-json-plus", "--message-format-version", "0.1"], {
    env: { ...process.env, CARGO_NET_OFFLINE: "true", RUST_TEST_THREADS: String(profile.testThreads), NEXTEST_EXPERIMENTAL_LIBTEST_JSON: "1" },
    ...evidence("execution"), liveStdout: true,
  });
  verifyExecution(events, observed[shard]);
  let coverageEvidence = {};
  if (profile.instrumented) {
  const coverageFile = path.join(output, "coverage.lcov");
  await command(["llvm-cov", "report", "--lcov", "--output-path", coverageFile], { env: { ...process.env, CARGO_NET_OFFLINE: "true" }, ...evidence("coverage") });
  const coverage = validateLcov(readFileSync(coverageFile, "utf8"));
  coverageEvidence = { coverageSha256: await fileHash(coverageFile), coverage };
  }
  verifyIdentity(manifest.identity, await identity(phase => evidence(`final-${phase}`), profile));
  writeJson(path.join(output, "receipt.json"), { schema: 1, sourceSha: manifest.identity.sourceSha, runId: manifest.identity.runId, runAttempt: manifest.identity.runAttempt, shard, archiveSha256: manifest.archiveSha256, manifestSha256: await fileHash(path.join(directory, "manifest.json")), ...coverageEvidence, ...(!profile.instrumented ? { identity: manifest.identity, featureResolutionSha256: manifest.featureResolutionSha256, inventoryFiles: manifest.inventoryFiles, selectedInventorySha256: await fileHash(path.join(output, "selected-inventory.json")) } : {}), executionSha256: await fileHash(path.join(output, "execution.jsonl")), seconds: (performance.now() - started) / 1000, executedTests: observed[shard].filter(row => row.selected).length, totalTests: observed[0].length });
  console.log(`Shard ${shard}/${profile.partitions.length} passed exact inventory${profile.instrumented ? " and coverage" : ""} validation.`);
}

// Pure cross-platform collection: producer job outputs are authority, never this
// collector's platform/root or an artifact's self-reported checksum.
export async function collectMacRemaining(directory, outputs, trusted) {
  requireDigest(trusted?.manifestSha256); requireDigest(trusted?.archiveSha256);
  assert.deepEqual(trusted.jobResults, { native: "success", producer: "success", consumers: ["success", "success"] }, "All native archive job results must be success");
  assert.match(trusted.sourceSha ?? "", /^[a-f0-9]{40}$/u, "Expected source SHA required");
  assert.match(trusted.runId ?? "", /^[1-9]\d*$/u, "Expected run ID required");
  assert.match(trusted.runAttempt ?? "", /^[1-9]\d*$/u, "Expected attempt required");
  assert.equal(await fileHash(path.join(directory, "manifest.json")), trusted.manifestSha256, "Trusted manifest digest mismatch");
  const manifest = readJson(path.join(directory, "manifest.json"));
  const profile = archiveProfile("macos-remaining");
  assert.equal(manifest.schema, 1, "Unsupported archive manifest");
  assert.equal(manifest.identity.archiveProfile, profile.name, "Wrong archive profile");
  assert.equal(manifest.identity.platform, "darwin", "Wrong producer platform");
  for (const key of ["sourceSha", "runId", "runAttempt"]) assert.equal(manifest.identity[key], trusted[key], `Stale producer ${key}`);
  assert.equal(manifest.archiveSha256, trusted.archiveSha256, "Trusted archive digest mismatch");
  assert.deepEqual(manifest.scheduling, scheduling(profile), "Wrong archive scheduling");
"}

