// Darwin's default unpacked line tables live in compiler object files. Keep only
// the selected runtime binaries' dSYMs, using official Nextest archive extras.
export function macDebugSymbolPaths(binaries, root) {
  verifyLayout(binaries, root);
  const target = path.join(root, "target");
  const selected = Object.values(binaries["rust-binaries"]).map(binary => binary["binary-path"]);
  for (const values of Object.values(binaries["rust-build-meta"]["non-test-binaries"] ?? {}))
    for (const binary of values) selected.push(path.resolve(target, binary.path));
  for (const binary of selected) {
    const relative = path.relative(target, binary);
    assert.ok(relative && !relative.startsWith("..") && !path.isAbsolute(relative), "Debug executable must remain under checkout target");
  }
  return [...new Set(selected)].sort();
}
async function verifyMacDebugSymbols(binaries, root, expected) {
  const target = path.join(root, "target");
  assert.deepEqual(expected.map(row => row.binary), macDebugSymbolPaths(binaries, root).map(binary => path.relative(target, binary)), "Archived debug symbol inventory differs");
  for (const row of expected) {
    const bundle = path.join(target, `${row.binary}.dSYM`);
    assert.equal(await fileHash(path.join(bundle, "Contents", "Resources", "DWARF", path.basename(row.binary))), row.dwarfSha256, "Archived debug line tables differ");
    assert.equal(await fileHash(path.join(bundle, "Contents", "Info.plist")), row.plistSha256, "Archived debug symbol metadata differs");
  }
}
